"""Export trained model to GGUF format and register with Ollama.

Handles the final step of the distillation pipeline: converting a fine-tuned
LoRA adapter into a quantized GGUF file suitable for local inference via Ollama.
"""

import subprocess
import shutil
from pathlib import Path
from dataclasses import dataclass


@dataclass
class ExportResult:
    """Result from GGUF export."""

    gguf_path: Path
    size_bytes: int
    quantization: str
    modelfile_path: Path | None


def export_gguf(
    model_path: str | Path,
    output_dir: str | Path | None = None,
    quantization: str = "Q4_K_M",
) -> ExportResult:
    """Export a fine-tuned model to GGUF format.

    Uses Unsloth's built-in GGUF conversion (``save_pretrained_gguf``).

    Args:
        model_path: Path to the saved LoRA adapter directory.
        output_dir: Directory for the GGUF file. Defaults to the adapter's parent.
        quantization: GGUF quantization level (e.g. Q4_K_M, Q5_K_M, Q8_0).

    Returns:
        ExportResult with the GGUF path, size, and generated Modelfile path.

    Raises:
        ImportError: If unsloth is not installed.
        FileNotFoundError: If model_path does not exist.
        RuntimeError: If the GGUF export fails to produce the expected file.
    """
    model_path = Path(model_path)
    if not model_path.exists():
        raise FileNotFoundError(f"Model not found: {model_path}")

    output_dir = Path(output_dir or model_path.parent).expanduser()
    output_dir.mkdir(parents=True, exist_ok=True)

    gguf_name = f"{model_path.name}-{quantization.lower()}.gguf"
    gguf_path = output_dir / gguf_name

    # Lazy import -- fail fast with clear message
    try:
        from unsloth import FastLanguageModel  # type: ignore[import-untyped]
    except ImportError:
        raise ImportError(
            "Unsloth is required for GGUF export. Install with:\n"
            "  pip install -e '.[distill]'   # from source (alpha)\n"
            "  pip install 'strata-memory[distill]'   # once published to PyPI"
        )

    print(f"Loading model from {model_path}")
    model, tokenizer = FastLanguageModel.from_pretrained(
        model_name=str(model_path),
        max_seq_length=2048,
        load_in_4bit=True,
    )

    print(f"Exporting to GGUF ({quantization})")
    # Unsloth's method expects the quantization with hyphens (q4-k-m)
    quant_method = quantization.lower().replace("_", "-")
    model.save_pretrained_gguf(
        str(output_dir / model_path.name),
        tokenizer,
        quantization_method=quant_method,
    )

    # Unsloth names the file slightly differently -- find it
    if not gguf_path.exists():
        for f in output_dir.glob("*.gguf"):
            if model_path.name in f.name:
                f.rename(gguf_path)
                break

    if not gguf_path.exists():
        raise RuntimeError(f"GGUF export failed -- expected file at {gguf_path}")

    size = gguf_path.stat().st_size
    print(f"Exported: {gguf_path} ({size / 1024 / 1024:.1f} MB)")

    # Generate Ollama Modelfile
    modelfile_path = _generate_modelfile(gguf_path, output_dir)

    return ExportResult(
        gguf_path=gguf_path,
        size_bytes=size,
        quantization=quantization,
        modelfile_path=modelfile_path,
    )


def find_latest_model(models_dir: str | Path | None = None) -> Path:
    """Find the most recently modified model directory in ~/.strata/models/.

    Args:
        models_dir: Override the default models directory.

    Returns:
        Path to the most recent model directory.

    Raises:
        FileNotFoundError: If no model directories are found.
    """
    models_dir = Path(models_dir or "~/.strata/models").expanduser()
    if not models_dir.exists():
        raise FileNotFoundError(f"Models directory not found: {models_dir}")

    candidates = [
        d for d in models_dir.iterdir()
        if d.is_dir() and d.name.startswith("strata-")
    ]

    if not candidates:
        raise FileNotFoundError(
            f"No trained models found in {models_dir}. "
            "Run 'strata-distill start' first."
        )

    # Sort by modification time, most recent first
    candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return candidates[0]


def _generate_modelfile(gguf_path: Path, output_dir: Path) -> Path:
    """Generate an Ollama Modelfile for the exported GGUF.

    The Modelfile configures low temperature and a system prompt appropriate
    for structured knowledge extraction tasks.

    Args:
        gguf_path: Absolute path to the GGUF model file.
        output_dir: Directory to write the Modelfile into.

    Returns:
        Path to the generated Modelfile.
    """
    modelfile_path = output_dir / "Modelfile"

    content = (
        f"FROM {gguf_path.resolve()}\n"
        "\n"
        "PARAMETER temperature 0.1\n"
        "PARAMETER num_predict 2048\n"
        "\n"
        "SYSTEM You are a knowledge extraction assistant. "
        "Extract structured knowledge entries from coding session transcripts. "
        "Output valid JSON only.\n"
    )
    modelfile_path.write_text(content)
    print(f"Modelfile written to {modelfile_path}")
    return modelfile_path


def register_ollama(
    modelfile_path: str | Path,
    model_name: str = "strata-extraction-7b",
) -> bool:
    """Register the model with Ollama using ``ollama create``.

    Args:
        modelfile_path: Path to the Ollama Modelfile.
        model_name: Name to register the model under in Ollama.

    Returns:
        True if successful, False if Ollama is not available or the command fails.
    """
    if not shutil.which("ollama"):
        print("Ollama not found in PATH. Install from https://ollama.com")
        print(f"Then run: ollama create {model_name} -f {modelfile_path}")
        return False

    print(f"Registering model as '{model_name}' in Ollama...")
    try:
        result = subprocess.run(
            ["ollama", "create", model_name, "-f", str(modelfile_path)],
            capture_output=True,
            text=True,
            timeout=300,
        )
        if result.returncode == 0:
            print(f"Model registered: ollama run {model_name}")
            return True
        else:
            print(f"Ollama create failed: {result.stderr}")
            return False
    except subprocess.TimeoutExpired:
        print("Ollama create timed out after 300s")
        return False
    except Exception as e:
        print(f"Failed to register with Ollama: {e}")
        return False
